-- Course-code harmonisation, BEICT Year 2 Semester 2.
--
-- Marks tables (acad_results, acad_course_registration) are moved exactly: each row is
-- recorded in bak_codeharmonise_20260812 first and the UPDATE is driven from that record,
-- and a row is never moved onto a (student, course, sitting) that already holds one -
-- those collisions are conflicting marks, so they stay put and get reported.
--
-- Ancillary tables (settings, allocations, audit) carry their own unique keys. They use
-- UPDATE IGNORE so one pre-existing duplicate cannot abort the whole migration, then the
-- backup is reconciled: any row that did not actually move has its record removed, so the
-- backup never claims a change that did not happen.
CREATE TABLE IF NOT EXISTS campus_dynamics.bak_codeharmonise_20260812 (
  loc VARCHAR(120) NOT NULL, pk_col VARCHAR(40) NOT NULL, pk_val BIGINT NOT NULL,
  old_code VARCHAR(60) NOT NULL, new_code VARCHAR(60) NOT NULL, changed_at DATETIME NOT NULL,
  KEY(loc,old_code), KEY(pk_val)) ENGINE=InnoDB DEFAULT CHARSET=utf8;
START TRANSACTION;
INSERT INTO campus_dynamics.bak_codeharmonise_20260812 (loc,pk_col,pk_val,old_code,new_code,changed_at) SELECT 'campus_dynamics.acad_examresults_faculty.course_id','ID',t.`ID`,'BCU 2203','BCU2203',NOW() FROM `campus_dynamics`.`acad_examresults_faculty` t WHERE t.`course_id` = 'BCU 2203';
UPDATE IGNORE `campus_dynamics`.`acad_examresults_faculty` SET `course_id` = 'BCU2203' WHERE `ID` IN (SELECT pk_val FROM campus_dynamics.bak_codeharmonise_20260812 WHERE loc='campus_dynamics.acad_examresults_faculty.course_id' AND old_code='BCU 2203' AND new_code='BCU2203');
DELETE FROM campus_dynamics.bak_codeharmonise_20260812 WHERE loc='campus_dynamics.acad_examresults_faculty.course_id' AND old_code='BCU 2203' AND new_code='BCU2203' AND pk_val IN (SELECT `ID` FROM `campus_dynamics`.`acad_examresults_faculty` WHERE `course_id`='BCU 2203');
INSERT INTO campus_dynamics.bak_codeharmonise_20260812 (loc,pk_col,pk_val,old_code,new_code,changed_at) SELECT 'campus_dynamics.acad_examresults_faculty_settings.course_id','ID',t.`ID`,'BCU 2203','BCU2203',NOW() FROM `campus_dynamics`.`acad_examresults_faculty_settings` t WHERE t.`course_id` = 'BCU 2203';
